```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string wordToCount; // palabra a contar
    std::string line;         // línea del archivo
    int count = 0;            // contador de apariciones

    // pedir palabra a contar al usuario
    std::cout << "Introduzca la palabra a contar: ";
    std::cin >> wordToCount;

    // abrir el archivo para leer
