    if (!file.is_open()) {
        std::cerr << "Error al abrir el archivo." << std::endl;
        return 1;
    }

    // leer línea por línea y contar apariciones
    while (getline(file, line)) {
        std::transform(line.begin(), line.end(), line.begin(), ::tolower); // convertir a minúsculas para contar palabras iguales
        size_t pos = line.find(wordToCount);
        while (pos != std::string::npos) {
            count++;
            pos = line.find(wordToCount, pos + 1); // buscar la siguiente aparición
        }
    }

    // cerrar el archivo
    file.close();

    // imprimir resultado
    std::cout << "La palabra \"" << wordToCount << "\" aparece " << count << " veces en el archivo." << std::endl;

    return 0;
}
